/** Previous sheet signature; the backdrop defaults to the active ground. */
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun SbBottomSheet(
    onDismissRequest: () -> Unit,
    modifier: Modifier = Modifier,
    sheetState: SheetState = rememberModalBottomSheetState(),
    title: String? = null,
    content: @Composable ColumnScope.() -> Unit,
) {
    SbBottomSheet(onDismissRequest, modifier, sheetState, title, SebaroTheme.colors.bg, content)
}

/**
 * Bottom sheet for pickers (D46): ground bg, the 2 dp ink layer line along the top edge and its 16 dp corners, no
 * shadow, no tonal elevation, no drag handle, the palette's scrim. Never for evidence: claim rows expand in place.
 * [title] draws the head of spec/02 §4.7 (EBE-04): the title in title 20/28 as a heading, then the close
 * button „Schließen“ (SbIconButton, 48 dp, [onDismissRequest]); the sheet closes without motion, as on the web. With a
 * title the content needs no group title of its own (SbRadioChoice(title = null)). The scrim's TalkBack name is
 * M3's and Compose UI's string resource „close_sheet“ (German „Tabelle schließen“), which the wrapper cannot set
 * (spec/02 §4.7): the app overrides that resource (§14.1).
 */
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun SbBottomSheet(
    onDismissRequest: () -> Unit,
    modifier: Modifier = Modifier,
    sheetState: SheetState = rememberModalBottomSheetState(),
    title: String? = null,
    backdropColor: Color,
    content: @Composable ColumnScope.() -> Unit,
) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val m = sbMessages()
    val overlay = t.elevation.overlay
    val shape = RoundedCornerShape(topStart = t.radius.sheet, topEnd = t.radius.sheet)
    ModalBottomSheet(
        onDismissRequest = onDismissRequest,
        modifier = modifier,
        sheetState = sheetState,
        shape = shape,
        containerColor = overlay.surface,
        contentColor = c.text,
        tonalElevation = 0.dp,
        scrimColor = c.scrim,
        dragHandle = null,
    ) {
        SbSheetSystemBars(overlay.surface, c.scrim.compositeOver(backdropColor))
        // The line is drawn on the sheet's content, not on [modifier]: M3 (1.3 and 1.4) moves the sheet by its offset
        // after the modifier it is given, so a line drawn there stays at the window's top (seen in the render, §18).
        Column(
            Modifier.fillMaxWidth().drawWithContent {
                drawContent()
                val line = overlay.borderWidth.toPx()
                // clip in the sheet's own coordinates, stroke on the inset outline: a clip inside the inset would cut
                // the outer half of the stroke (a 1 dp line 1 dp below the edge, seen in the render, §18)
                clipRect(bottom = t.radius.sheet.toPx() + line / 2f) {
                    inset(line / 2f) {
                        drawOutline(shape.createOutline(size, layoutDirection, this), overlay.borderColor, style = Stroke(line))
                    }
                }
            },
        ) {
            if (title != null) SbSheetHead(title, m.sheetClose, onDismissRequest)
            content()
        }
    }
}

/** Icons follow each bar's actual ground: scrim over the app above, sheet surface below.
 * Runs before every draw, after M3 has updated its own dialog parameters on both supported BOMs.
 * Only the sheet's window is touched. Removing it cannot change the Activity's bars.
 */
@Composable
private fun SbSheetSystemBars(surface: Color, behindScrim: Color) {
    val view = LocalView.current
    val surfaceNow by rememberUpdatedState(surface)
    val scrimNow by rememberUpdatedState(behindScrim)
    DisposableEffect(view) {
        val window = generateSequence(view as ViewParent?) { it.parent }
            .filterIsInstance<DialogWindowProvider>().firstOrNull()?.window
        val controller = window?.let { WindowCompat.getInsetsController(it, view) }
        val observer = view.viewTreeObserver
        val listener = ViewTreeObserver.OnPreDrawListener {
            controller?.isAppearanceLightStatusBars = sbSheetDarkIcons(scrimNow)
            controller?.isAppearanceLightNavigationBars = sbSheetDarkIcons(surfaceNow)
            true
        }
        observer.addOnPreDrawListener(listener)
        onDispose { if (observer.isAlive) observer.removeOnPreDrawListener(listener) }
    }
}

/** Black icons when they have the greater contrast against an opaque ground (equal at luminance 0.179). */
internal fun sbSheetDarkIcons(ground: Color): Boolean = ground.luminance() > 0.179f

/** The head of a sheet (spec/02 §4.7, the web's sb-sheet__head): title 20/28 as a heading, „Schließen“ at the end. */
@Composable
private fun SbSheetHead(title: String, close: String, onClose: () -> Unit) {
    val t = SebaroTheme.tokens
    Row(
        Modifier
            .fillMaxWidth()
            .heightIn(min = t.size.targetTouch)
            .padding(start = t.spacing.gutter, end = t.spacing.gutter, top = t.space.s2),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(t.space.s2),
    ) {
        SbWrapText(
            title,
            SebaroTheme.typography.title,
            SebaroTheme.colors.text,
            Modifier.weight(1f).semantics { heading() },
        )
        SbIconButton(SebaroIcons.Outline.Close, close, onClose)
    }
}
